import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("A vendor name already taken in my tenant is rejected case-insensitively", { tag: "@VEN-03" }, async ({ apiAs, factory }) => {
  // Arrange: an existing vendor in the member's tenant, with a unique name
  const member = await apiAs("member");
  const existing = await factory.vendor({ as: "member", name: uniqueName("Acme Freight"), category: "logistics" });

  // Act: create a vendor whose name differs only by case
  const response = await member.post("/api/vendors", {
    data: {
      name: existing.name.toLowerCase(),
      category: "logistics",
      contact_email: "ops@acmefreight.example",
    },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_name_taken");
});
